import React, { useState } from 'react';
import { Layout, Tabs, message } from 'antd';
import ThresholdForm from '../components/threshold/ThresholdForm';
import ThresholdPreview from '../components/threshold/ThresholdPreview';
import ThresholdAuditTable from '../components/threshold/ThresholdAuditTable';
import api from '../services/api';

const { Content } = Layout;
const { TabPane } = Tabs;

/**
 * ThresholdManagement - Main page for threshold governance
 * Generated by Copilot
 */
const ThresholdManagement = () => {
  const [currentDraftId, setCurrentDraftId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('1');

  const handleCreateDraft = async (payload) => {
    setLoading(true);
    try {
      const response = await api.post('/api/v1/admin/thresholds/draft', payload);
      setCurrentDraftId(response.data.id);
      message.success(`草稿已创建 (ID: ${response.data.id})`);
      // Switch to preview tab
      setActiveTab('2');
    } catch (error) {
      message.error('创建草稿失败: ' + (error.response?.data?.error || error.message));
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const handlePublishSuccess = (data) => {
    message.success(`配置已发布！版本: ${data.version}`);
    setCurrentDraftId(null);
    // Switch to audit tab
    setActiveTab('3');
  };

  return (
    <Layout style={{ minHeight: '100vh' }}>
      <Content style={{ padding: '24px' }}>
        <h1>阈值治理配置</h1>
        <p style={{ marginBottom: '24px', color: '#666' }}>
          管理血压和心率的健康阈值配置。创建草稿 → 预览效果 → 发布为活跃配置。
        </p>

        <Tabs activeKey={activeTab} onChange={setActiveTab}>
          <TabPane tab="创建/编辑草稿" key="1">
            <ThresholdForm 
              onSubmit={handleCreateDraft} 
              loading={loading}
            />
          </TabPane>

          <TabPane tab="预览与发布" key="2">
            <ThresholdPreview 
              draftId={currentDraftId}
              onPublish={handlePublishSuccess}
            />
            {!currentDraftId && (
              <div style={{ textAlign: 'center', padding: '40px', color: '#999' }}>
                请先在"创建/编辑草稿"标签页中创建一个草稿配置
              </div>
            )}
          </TabPane>

          <TabPane tab="审计日志" key="3">
            <ThresholdAuditTable />
          </TabPane>
        </Tabs>
      </Content>
    </Layout>
  );
};

export default ThresholdManagement;
